import React, { useState, useRef, useEffect, useCallback } from 'react';
import { attendanceAPI } from './api_service';

const CameraRecognition = ({ addNotification }) => {
  // Refs
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const timeoutRef = useRef(null);
  const isProcessingRef = useRef(false);
  const canvasRef = useRef(document.createElement('canvas'));

  // States
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [autoMode, setAutoMode] = useState(true);
  const [frameCount, setFrameCount] = useState(0);
  const [lastDetection, setLastDetection] = useState(null);

  // --- Initialisation de la Caméra ---
  useEffect(() => {
    const startCamera = async () => {
      try {
        console.log('🎥 Démarrage caméra...');
        const stream = await navigator.mediaDevices.getUserMedia({
          video: {
            facingMode: 'user',
            width: { ideal: 1280 },
            height: { ideal: 720 }
          },
          audio: false
        });

        streamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }
      } catch (err) {
        console.error('❌ Erreur caméra:', err);
        setError("Impossible d'accéder à la caméra");
        addNotification?.('❌ Erreur d\'accès caméra', 'error');
      }
    };

    startCamera();

    return () => stopCamera();
  }, [addNotification]);

  const stopCamera = useCallback(() => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setAutoMode(false);
    console.log('🛑 Caméra et processus arrêtés');
  }, []);

  // --- Logique de Capture (Base) ---
  const captureFrame = useCallback(async (quality = 0.8) => {
    if (!videoRef.current || videoRef.current.paused || videoRef.current.ended) return null;

    const video = videoRef.current;
    const canvas = canvasRef.current;

    // Ajuster la taille du canvas si nécessaire
    if (canvas.width !== video.videoWidth) {
      canvas.width = video.videoWidth || 640;
      canvas.height = video.videoHeight || 480;
    }

    const ctx = canvas.getContext('2d');
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

    // On retourne la base64 (jpeg pour plus de légèreté que png)
    return canvas.toDataURL('image/jpeg', quality);
  }, []);

  // --- Mode Automatique (Boucle récursive sécurisée) ---
  useEffect(() => {
    if (!autoMode) {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      return;
    }

    const runScanner = async () => {
      if (isProcessingRef.current) {
        timeoutRef.current = setTimeout(runScanner, 500);
        return;
      }

      const imageBase64 = await captureFrame(0.7); // Qualité réduite pour l'auto-scan
      if (!imageBase64) {
        timeoutRef.current = setTimeout(runScanner, 500);
        return;
      }

      try {
        isProcessingRef.current = true;
        setFrameCount(f => f + 1);

        const response = await attendanceAPI.recognize(imageBase64);
        const data = response?.data;

        if (data?.success && data?.student) {
          setResult({
            success: true,
            name: data.student,
            email: data.email || 'N/A',
            confidence: (data.confidence * 100).toFixed(1),
            attendanceId: data.attendance_id,
            timestamp: new Date().toLocaleTimeString(),
            message: `✅ ${data.student} enregistré!`
          });
          setLastDetection(new Date().toLocaleTimeString());
          addNotification?.(`✅ ${data.student} détecté`, 'success');

          // Pause de 3 secondes après détection réussie
          setAutoMode(false);
          setTimeout(() => setAutoMode(true), 3000);
          return; // Sortir de la boucle, le prochain useEffect relancera
        }
      } catch (err) {
        console.warn('⚠️ Erreur scan:', err.message);
      } finally {
        isProcessingRef.current = false;
        if (autoMode) {
          timeoutRef.current = setTimeout(runScanner, 500);
        }
      }
    };

    timeoutRef.current = setTimeout(runScanner, 500);

    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, [autoMode, addNotification, captureFrame]);

  // --- Capture Manuelle ---
  const handleManualCapture = async () => {
    if (loading) return;
    setLoading(true);
    setError(null);

    const imageBase64 = await captureFrame(0.9); // Meilleure qualité en manuel

    try {
      const response = await attendanceAPI.recognize(imageBase64);
      const data = response?.data;

      if (data?.success) {
        setResult({
          success: true,
          name: data.student,
          email: data.email,
          confidence: (data.confidence * 100).toFixed(1),
          attendanceId: data.attendance_id,
          timestamp: new Date().toLocaleTimeString(),
          message: `✅ ${data.student} enregistré!`
        });
        addNotification?.(`✅ ${data.student} détecté`, 'success');
      } else {
        const failData = {
          success: false,
          message: data?.message || 'Visage non reconnu',
          confidence: ((data?.confidence || 0) * 100).toFixed(1)
        };
        setResult(failData);
        setError(failData.message);
        addNotification?.('⚠️ Visage non reconnu', 'error');
      }
    } catch (err) {
      const msg = err?.response?.data?.message || err.message || 'Erreur serveur';
      setError(msg);
      addNotification?.(`❌ ${msg}`, 'error');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.container}>
      <h1 style={styles.title}>👤 Reconnaissance Faciale</h1>

      <div style={styles.videoContainer}>
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted
          style={styles.video}
        />

        <div style={{
          ...styles.statusBadge,
          background: autoMode ? 'rgba(34, 197, 94, 0.9)' : 'rgba(107, 114, 128, 0.9)'
        }}>
          {autoMode ? '🔄 Scanning...' : '⏸️ Pause'}
        </div>

        <div style={styles.frameCounter}>
          Frames traitées: {frameCount}
        </div>
      </div>

      <div style={styles.actions}>
        <button
          onClick={handleManualCapture}
          disabled={loading}
          style={{
            ...styles.btn,
            background: loading ? '#94A3B8' : '#10B981'
          }}
        >
          {loading ? '⏳ Traitement...' : '📸 Capturer'}
        </button>

        <button
          onClick={() => setAutoMode(!autoMode)}
          style={{
            ...styles.btn,
            background: autoMode ? '#EF4444' : '#6366F1'
          }}
        >
          {autoMode ? '⏸️ Arrêter Auto' : '▶️ Démarrer Auto'}
        </button>

        <button
          onClick={stopCamera}
          style={{ ...styles.btn, background: '#64748B' }}
        >
          🛑 Fermer Caméra
        </button>
      </div>

      {autoMode && (
        <div style={styles.autoStatus}>
          <span className="pulse-dot" style={styles.pulse} />
          Détection continue active (500ms)
        </div>
      )}

      {lastDetection && !result && (
        <div style={styles.lastDetectionBox}>
          ⏰ Dernière détection à: {lastDetection}
        </div>
      )}

      {error && <div style={styles.errorBox}>❌ {error}</div>}

      {result && (
        <div style={{
          ...styles.resultBox,
          borderLeft: result.success ? '5px solid #10B981' : '5px solid #EF4444'
        }}>
          {result.success ? (
            <>
              <h3 style={{ color: '#10B981', margin: '0 0 12px 0' }}>{result.message}</h3>
              <div style={styles.resultGrid}>
                <p><strong>👤 Nom:</strong> {result.name}</p>
                <p><strong>📧 Email:</strong> {result.email}</p>
                <p><strong>🎯 Confiance:</strong> {result.confidence}%</p>
                <p><strong>🆔 ID:</strong> {result.attendanceId}</p>
                <p><strong>🕒 Heure:</strong> {result.timestamp}</p>
              </div>
              <button 
                onClick={() => setResult(null)} 
                style={styles.clearBtn}
              >Effacer</button>
            </>
          ) : (
            <div style={{ textAlign: 'center' }}>
              <h3 style={{ color: '#EF4444', margin: 0 }}>❌ Non Reconnu</h3>
              <p>{result.message} ({result.confidence}%)</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

